<?php
require_once __DIR__.'/../includes/bootstrap.php';$method=$_SERVER['REQUEST_METHOD']??'GET';
function sms_user(array $u,int $current=0):array{$u['id']='u'.$u['id'];$u['name']=$u['full_name'];$u['role']=$u['role']==='Admin'?'Administrator':'Registrar';$u['joined']=$u['created_at'];$u['lastActive']='—';$u['initials']=implode('',array_map(fn($p)=>substr($p,0,1),array_slice(preg_split('/\s+/',trim($u['full_name'])),0,2)));$u['color']='#2451e0';$u['isCurrentUser']=(int)substr($u['id'],1)===$current;unset($u['full_name'],$u['created_at']);return $u;}
try{$db=database();
 if($method==='GET'){$admin=require_admin();$q=$db->query("SELECT id,full_name,email,role,status,created_at FROM users WHERE role<>'Student' ORDER BY created_at DESC,id DESC");json_response(['ok'=>true,'users'=>array_map(fn($u)=>sms_user($u,(int)$admin['id']),$q->fetchAll())]);}
 if($method==='POST'){$admin=require_admin();require_csrf();$d=request_data();$name=clean_text($d['name']??$d['full_name']??'',150);$email=strtolower(clean_text($d['email']??'',254));$pass=is_string($d['password']??null)?$d['password']:'';$role=($d['role']??'')==='Administrator'?'Admin':'User';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<10)json_response(['ok'=>false,'error'=>'Provide a name, valid email, and a temporary password of at least 10 characters.'],422);$q=$db->prepare('INSERT INTO users(full_name,email,password,role) VALUES(:name,:email,:pass,:role)');try{$q->execute(['name'=>$name,'email'=>$email,'pass'=>password_hash($pass,PASSWORD_DEFAULT),'role'=>$role]);}catch(PDOException $e){if($e->getCode()==='23000')json_response(['ok'=>false,'error'=>'That email already has an account.'],409);throw $e;}json_response(['ok'=>true,'message'=>'Account created.']);}
 if($method==='PUT'){$admin=require_admin();require_csrf();$d=request_data();$id=(int)preg_replace('/\D/','',(string)($d['id']??''));$role=($d['role']??'')==='Administrator'?'Admin':'User';$status=clean_text($d['status']??'',15);if(!$id||!in_array($status,['Active','Inactive'],true))json_response(['ok'=>false,'error'=>'Choose a valid role and status.'],422);if($id===(int)$admin['id']&&($role!=='Admin'||$status!=='Active'))json_response(['ok'=>false,'error'=>'You cannot deactivate or demote yourself.'],422);$q=$db->prepare('SELECT id,role,status FROM users WHERE id=:id');$q->execute(['id'=>$id]);$old=$q->fetch();if(!$old)json_response(['ok'=>false,'error'=>'User not found.'],404);if($old['role']==='Student')json_response(['ok'=>false,'error'=>'Student account access is managed through the student record.'],422);if($old['role']==='Admin'&&$old['status']==='Active'&&($role!=='Admin'||$status!=='Active')&&(int)$db->query("SELECT COUNT(*) FROM users WHERE role='Admin' AND status='Active'")->fetchColumn()<=1)json_response(['ok'=>false,'error'=>'At least one active administrator must remain.'],422);$q=$db->prepare('UPDATE users SET role=:role,status=:status WHERE id=:id');$q->execute(['role'=>$role,'status'=>$status,'id'=>$id]);json_response(['ok'=>true,'message'=>'User permissions updated.']);}
 if($method==='DELETE'){$admin=require_admin();require_csrf();$d=request_data();$id=(int)preg_replace('/\D/','',(string)($d['id']??''));if(!$id||$id===(int)$admin['id'])json_response(['ok'=>false,'error'=>'You cannot delete your own account.'],422);$q=$db->prepare('SELECT role,status FROM users WHERE id=:id');$q->execute(['id'=>$id]);$old=$q->fetch();if(!$old)json_response(['ok'=>false,'error'=>'User not found.'],404);if($old['role']==='Student')json_response(['ok'=>false,'error'=>'Delete a student and its login from the student record.'],422);if($old['role']==='Admin'&&$old['status']==='Active'&&(int)$db->query("SELECT COUNT(*) FROM users WHERE role='Admin' AND status='Active'")->fetchColumn()<=1)json_response(['ok'=>false,'error'=>'At least one active administrator must remain.'],422);$q=$db->prepare('DELETE FROM users WHERE id=:id');$q->execute(['id'=>$id]);json_response(['ok'=>true,'message'=>'User deleted.']);}
 json_response(['ok'=>false,'error'=>'Method not allowed.'],405);
}catch(PDOException $e){error_log('EduCore users API: '.$e->getMessage());json_response(['ok'=>false,'error'=>'User accounts could not be loaded or saved.'],503);}
